INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(11911336, 'Spellbook of the Grand Circle', '大轮之魔导书', '大輪の魔導書', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己的卡组·墓地·除外状态的4只「灵使」怪兽加入手卡（相同属性最多1只）。那之后，选自己2张手卡回到卡组。 ②：把墓地的这张卡除外才能发动。自己的手卡·场上的「灵使」、「凭依装着」怪兽作为融合素材，把1只融合怪兽融合召唤。在那次融合召唤成功时对方不能把魔法·陷阱·怪兽的效果发动。'),
(56981417, 'Spellbook of the Master', '创造之魔导书', 'セフェルの魔導書', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有魔法师族怪兽存在的场合，把这张卡以外的手卡1张「魔导书」卡给对方观看，以「创造之魔导书」以外的自己墓地1张「魔导书」通常魔法卡为对象才能发动。这张卡的效果变成和那张通常魔法卡发动时的效果相同。'),
(88616795, 'Spellbook of Wisdom', '律法之魔导书', 'トーラの魔導書', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：可以以场上1只魔法师族怪兽为对象，从以下效果选择1个发动。 ●这个回合，那只表侧表示怪兽不受这张卡以外的魔法卡的效果影响。 ●这个回合，那只表侧表示怪兽不受陷阱卡的效果影响。'),
(96677818, 'Spellbook Organization', '魔导书整理', '魔導書整理', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '翻开自己卡组最上面3张卡，将其按喜欢的顺序放回。对方不能确认这些卡。'),
(56321639, 'Spellbook Star Hall', '魔导书廊 埃图瓦勒', '魔導書廊エトワール', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，每次自己或者对方把名字带有「魔导书」的魔法卡发动，给这张卡放置1个魔力指示物。自己场上的魔法师族怪兽的攻击力上升这张卡放置的魔力指示物数量×100的数值。此外，有魔力指示物放置的这张卡被破坏送去墓地时，可以把持有这张卡放置的魔力指示物数量以下的等级的1只魔法师族怪兽从卡组加入手卡。'),
(3259760, 'Spellbound', '咒缚众', '呪縛衆', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：对方场上的全部表侧表示怪兽直到回合结束时不能解放，也不能作为融合·同调·超量·连接召唤的素材。'),
(73061465, 'Spellbreaker of the Ice Barrier', '冰结界的封魔团', '氷結界の封魔団', 'Effect Monster', 'Spellcaster', 'WATER', 4, 1200, 2000, '①：1回合1次，从手卡把1只「冰结界」怪兽送去墓地才能发动。这只怪兽表侧表示存在期间，直到下次的自己回合的结束时双方不能把魔法卡发动。'),
(20630765, 'Spellstone Sorcerer Karood', '魔石术师 克鲁德', '魔石術師 クルード', 'Effect Monster', 'Spellcaster', 'LIGHT', 3, 800, 1900, '1回合1次，每次这张卡以外的怪兽的效果发动，给这张卡放置1个魔石指示物（最多1个）。这张卡放置的魔石指示物每有1个，这张卡的守备力上升300。此外，1回合1次，可以把自己场上存在的1个魔石指示物取除，选择对方墓地存在的1张卡从游戏中除外。'),
(33245030, 'Sphere Kuriboh', '库里波球', 'クリボール', 'Effect Monster', 'Fiend', 'DARK', 1, 300, 200, '①：对方怪兽的攻击宣言时，把这张卡从手卡送去墓地才能发动。那只攻击怪兽变成守备表示。 ②：仪式召唤进行的场合，可以作为需要的等级数值的怪兽之内的1只，把墓地的这张卡除外。'),
(82693042, 'Sphere of Chaos', '混沌球体', '混沌球体', 'Effect Monster', 'Machine', 'DARK', 5, 1600, NULL, '这张卡只要在场上表侧表示存在，也当作光属性使用。这张卡1回合只有1次不会被战斗破坏。这张卡上级召唤成功时，可以从卡组把1只3星怪兽加入手卡。'),
(52121290, 'Spherous Lady', '蛇女郎', 'スフィラスレディ', 'Normal Monster', 'Rock', 'EARTH', 3, 400, 1400, '以为是美女而随便靠近的话，便会被吸干全身的血液。'),
(46148485, 'Sphinx of the Cycle', '转轮的斯芬克斯', '転輪のスフィンクス', 'Effect Monster', 'Rock', 'EARTH', 8, 2500, 3000, '这个卡名的①②的效果1回合各能使用1次。 ①：怪兽的表示形式变更的场合，从自己墓地把1张魔法卡除外才能发动。这张卡从手卡·墓地特殊召唤。 ②：自己主要阶段才能发动。从自己的卡组·墓地把「太阳之书」和「月之书」各最多1张在自己的魔法与陷阱区域盖放。 ③：1回合1次，场上的其他怪兽的表示形式变更的场合，以场上1张卡为对象才能发动。那张卡回到手卡。'),
(51402177, 'Sphinx Teleia', '斯芬克斯·迪蕾雅', 'スフィンクス・テーレイア', 'Effect Monster', 'Beast', 'LIGHT', 10, 2500, 3000, '场上有「光之金字塔」存在的场合，可以支付500基本分把这张卡从手卡特殊召唤。这张卡在召唤·特殊召唤的回合不能攻击。这张卡不能作从墓地的特殊召唤。这张卡战斗破坏守备表示怪兽的场合，给与对方基本分破坏的怪兽的守备力一半数值的伤害。'),
(56051648, 'Spider Egg', '蜘蛛卵', 'スパイダー・エッグ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方宣言直接攻击时，自己墓地昆虫族怪兽有3只以上存在的场合才能发动。把那只怪兽的攻击无效，在自己场上把3只「蜘蛛衍生物」（昆虫族·地·1星·攻/守100）攻击表示特殊召唤。'),
(56051649, 'Spider Token', '蜘蛛卵', 'スパイダー・エッグ', 'Token', 'Insect', NULL, NULL, NULL, NULL, NULL),
(69408987, 'Spider Web', '蜘蛛网', 'スパイダー・ウェブ', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '怪兽攻击宣言的场合，那只怪兽在伤害步骤结束时变成守备表示，直到从那只怪兽的控制者来看的下次的自己回合的结束阶段时不能把表示形式改变。'),
(26640671, 'Spiders'' Lair', '蜘蛛的领域', '蜘蛛の領域', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '1回合1次，选择自己场上表侧表示存在的1只昆虫族怪兽发动。和选择的怪兽进行战斗的对方怪兽在战斗阶段结束时变成守备表示，只要这张卡在场上存在不能把表示形式变更。'),
(85326399, 'Spike Seadra', '尖刺海龙', 'スパイクシードラ', 'Normal Monster', 'Sea Serpent', 'WATER', 5, 1600, 1300, '用身体的刺攻击敌人，并能放出电流。'),
(87511987, 'Spikebot', '尖钉头', 'スパイク・ヘッド', 'Normal Monster', 'Machine', 'DARK', 5, 1800, 1700, '地狱魔术师制造的机器士兵，不断地用双手的铁球对敌人和友军发动无差别攻击。'),
(98075147, 'Spiked Snail', '恶魔蜗牛', 'デビルツムリ', 'Normal Monster', 'Insect', 'DARK', 3, 700, 1300, '以黑暗力量进化了的蜗牛。有手有脚、动作迅速。'),
(6691855, 'Spikeshield with Chain', '附锁链的尖盾', '鎖付き尖盾', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '发动后这张卡变成攻击力上升500的装备卡，给场上1只怪兽装备。装备怪兽以守备表示进行战斗的场合，装备怪兽的守备力只在伤害计算时上升那个攻击力数值。'),
(22866836, 'Spin Turn', '超原地转向', '超信地旋回', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：可以从以下效果选择1个发动。 ●以自己场上1只攻击表示的机械族·地属性超量怪兽和对方场上1只怪兽为对象才能发动。那只自己怪兽的表示形式变更，那只对方怪兽破坏。 ●以自己场上1只守备表示的机械族·地属性超量怪兽和对方场上1张魔法·陷阱卡为对象才能发动。那只自己怪兽的表示形式变更，那张对方的魔法·陷阱卡破坏。'),
(42463414, 'Spined Gillman', '刺鱼人', 'ニードル・ギルマン', 'Effect Monster', 'Sea Serpent', 'WATER', 3, 1300, NULL, '①：只要这张卡在怪兽区域存在，自己场上的鱼族·海龙族·水族怪兽的攻击力上升400。'),
(44689689, 'Spinos Token', '朱罗纪・棘龙', 'ジュラック・スピノス', 'Token', 'Dinosaur', NULL, NULL, NULL, NULL, NULL),
(29477860, 'Spiral Discharge', '螺旋炮击', '螺旋砲撃', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：只要自己的怪兽区域有「龙骑士 盖亚」存在，对方只能选择「龙骑士 盖亚」作为攻击对象。 ②：自己的「龙骑士 盖亚」进行战斗的攻击宣言时，以场上1张卡为对象才能发动。那张卡破坏。'),
(82768499, 'Spiral Flame Strike', '螺旋之强袭爆裂', '螺旋のストライクバースト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：可以从以下效果选择1个发动。 ●自己场上有「异色眼」卡存在的场合，以场上1张卡为对象才能发动。那张卡破坏。 ●从卡组的怪兽以及自己的额外卡组的表侧表示的灵摆怪兽之中选1只7星「异色眼」怪兽加入手卡。'),
(38590361, 'Spiral Fusion', '螺旋结合', '螺旋融合', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从自己的手卡·场上把龙族融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。这个效果把「龙骑士 盖亚」特殊召唤的场合，那只怪兽攻击力上升2600，同1次的战斗阶段中最多2次可以向怪兽攻击。'),
(56461575, 'Spiral Reborn', '螺旋苏生', '螺旋蘇生', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己墓地1只7星以下的龙族怪兽为对象才能发动。那只怪兽特殊召唤。这个效果把「龙骑士 盖亚」特殊召唤的场合，那只怪兽不会成为对方的效果的对象，不会被对方的效果破坏。'),
(32626733, 'Spiral Serpent', '螺旋龙', 'スパイラルドラゴン', 'Normal Monster', 'Sea Serpent', 'WATER', 8, 2900, 2900, '传闻会制造海龙旋涡袭击人们的海龙。巨大的鳍所放出的螺旋形波浪能吞噬一切。'),
(49328340, 'Spiral Spear Strike', '螺旋枪杀', '螺旋槍殺', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：自己的「暗黑骑士 盖亚」「疾风之暗黑骑士 盖亚」「龙骑士 盖亚」向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。 ②：这张卡的①的效果适用让「龙骑士 盖亚」给与对方战斗伤害的场合发动。自己从卡组抽2张，那之后选1张手卡丢弃。'),
(53239672, 'Spirit Barrier', '灵魂障壁', 'スピリットバリア', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '只要自己场上存在怪兽，对这张卡的控制者的战斗伤害变为0。'),
(50418970, 'Spirit Burner', '灵魂火阵', 'スピリット・バーナー', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '1回合1次，可以把装备怪兽变成守备表示。装备怪兽从场上回到手卡让这张卡被送去墓地时，给与对方基本分600分伤害。这张卡在墓地存在的场合，可以作为自己的抽卡阶段时进行通常抽卡的代替，把这张卡加入手卡。'),
(48659020, 'Spirit Caller', '呼魂者', '魂を呼ぶ者', 'Flip Effect Monster', 'Spellcaster', 'LIGHT', 3, 1000, 1000, '反转：从自己墓地里特殊召唤1只3星以下的通常怪兽上场。'),
(91530236, 'Spirit Charmers', '精灵术的操控者', '精霊術の使い手', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：丢弃1张手卡才能发动。从卡组选「灵使」怪兽、「凭依装着」怪兽、「凭依」魔法·陷阱卡之内2张（同名卡最多1张）。那之内的1张加入手卡，另1张在自己场上盖放。'),
(20802187, 'Spirit Converter', '灵魂变换装置', 'スピリット変換装置', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，以自己场上1只超量怪兽为对象才能发动。选自己场上1只光属性·4星怪兽作为成为对象的超量怪兽的超量素材。 ②：这张卡从场上送去墓地的场合，以自己墓地2只雷族·光属性·4星的同名怪兽为对象发动。那些雷族·光属性怪兽加入手卡。'),
(69832741, 'Spirit Elimination', '灵魂消灭', '霊魂消滅', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '墓地的怪兽从游戏中除外的场合，用自己场上的怪兽从游戏中除外代替。这个效果发动的回合有效。'),
(16674846, 'Spirit Force', '气魄之力', 'スピリット・フォース', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方回合的战斗伤害计算时才能发动。那次战斗发生的对自己的战斗伤害变成0。那之后，可以把自己墓地存在的1只守备力1500以下的战士族调整加入手卡。'),
(71939275, 'Spirit Illusion', '死灵之残像', '死霊の残像', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '5星以上的恶魔族·不死族怪兽才能装备。这个卡名的①的效果1回合只能使用1次。 ①：可以从以下效果选择1个发动。 ●自己的手卡·场上的怪兽作为融合素材，把1只融合怪兽融合召唤。 ●把持有和装备怪兽相同种族·属性·攻击力的1只「多普勒衍生物」（5星·攻?/守0）在自己场上特殊召唤。 ②：装备怪兽和对方怪兽进行战斗的攻击宣言时才能发动。那只对方怪兽的攻击力下降装备怪兽的攻击力数值。'),
(94772232, 'Spirit Message "A"', '死之信息「T」', '死のメッセージ「T」', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡不用「通灵盘」的效果不能在场上出现。'),
(31893528, 'Spirit Message "I"', '死之信息「E」', '死のメッセージ「E」', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡不用「通灵盘」的效果不能在场上出现。'),
(30170981, 'Spirit Message "L"', '死之信息「H」', '死のメッセージ「H」', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡不用「通灵盘」的效果不能在场上出现。'),
(67287533, 'Spirit Message "N"', '死之信息「A」', '死のメッセージ「A」', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡不用「通灵盘」的效果不能在场上出现。'),
(13522325, 'Spirit of Flames', '炎之精灵 伊夫里特', '炎の精霊 イフリート', 'Effect Monster', 'Pyro', 'FIRE', 4, 1700, 1000, '这张卡不能通常召唤。从自己墓地把1只炎属性怪兽除外的场合可以特殊召唤。 ①：这张卡的攻击力在自己战斗阶段内上升300。'),
(14037717, 'Spirit of the Books', '书之精灵 飞鹰主教', '本の精霊 ホーク・ビショップ', 'Normal Monster', 'Winged Beast', 'WIND', 4, 1400, 1200, '书本的精灵，拥有非常高的智慧，发动多彩的攻击。'),
(53530069, 'Spirit of the Breeze', '微风之精灵', 'そよ風の精霊', 'Effect Monster', 'Fairy', 'WIND', 3, NULL, 1800, '只要这张卡在自己场上表侧攻击表示存在，每次自己的准备阶段回复1000基本分。'),
(26517393, 'Spirit of the Fall Wind', '里风之精灵', '裏風の精霊', 'Effect Monster', 'Fairy', 'WIND', 4, 1800, 900, '①：这张卡召唤的场合才能发动。从卡组把1只反转怪兽加入手卡。'),
(80770678, 'Spirit of the Harp', '竖琴精灵', 'ハープの精', 'Normal Monster', 'Fairy', 'LIGHT', 4, 800, 2000, '在天界弹奏竖琴的精灵。那音色使周围听众的心变得平静。'),
(34690519, 'Spirit of the Mountain', '山之精灵', '山の精霊', 'Normal Monster', 'Spellcaster', 'EARTH', 5, 1300, 1800, '据说听了它的笛音的人会失去力量。'),
(25343280, 'Spirit of the Pharaoh', '法老之灵', 'スピリッツ・オブ・ファラオ', 'Effect Monster', 'Zombie', 'LIGHT', 6, 2500, 2000, '这张卡不能进行通常召唤。这张卡只能通过「第一之棺」的效果进行特殊召唤。这张卡特殊召唤成功时，可以从自己的墓地里特殊召唤至多4只2星以下的不死族通常怪兽上场。'),
(4896788, 'Spirit of the Pot of Greed', '强欲之壶的精灵', '強欲な壺の精霊', 'Effect Monster', 'Fairy', 'LIGHT', 1, 100, 100, '①：「强欲之壶」发动的场合发动。那个把「强欲之壶」发动的玩家可以从卡组抽1张。这个效果在这张卡在怪兽区域表侧攻击表示存在的场合进行发动和处理。'),
(65685470, 'Spirit of the Six Samurai', '六武众的御灵代', '六武衆の御霊代', 'Union Effect Monster', 'Warrior', 'EARTH', 3, 500, 500, '1回合1次，自己的主要阶段时可以当作装备卡使用给自己场上的名字带有「六武众」的怪兽装备，或者把装备解除以表侧攻击表示特殊召唤。只在这个效果当作装备卡使用的场合，装备怪兽的攻击力·守备力上升500。装备怪兽战斗破坏对方怪兽的场合，自己从卡组抽1张卡。（1只怪兽可以装备的同盟最多1张。装备怪兽被破坏的场合，作为代替把这张卡破坏。）'),
(54615781, 'Spirit of the Winds', '风之精灵', '風の精霊', 'Normal Monster', 'Spellcaster', 'WIND', 5, 1700, 1400, '自在飞翔的风之精灵。心情不好的时候就会变成狂风。'),
(90829280, 'Spirit of Yubel', '尤贝尔之精灵', 'スピリット・オブ・ユベル', 'Effect Monster', 'Fiend', 'DARK', 10, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：对方怪兽的攻击宣言时才能发动。这张卡从手卡特殊召唤。 ②：这张卡特殊召唤的场合才能发动。从卡组选有「于贝尔」的卡名记述的1张魔法·陷阱卡加入手卡或在自己场上盖放。 ③：这张卡不会被战斗破坏，这张卡的战斗发生的对自己的战斗伤害变成0。 ④：这张卡被破坏的场合才能发动。自己的手卡·卡组·墓地·除外状态的1只「于贝尔」特殊召唤。'),
(85150300, 'Spirit Poacher', '精灵猎人', '精霊の狩人', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：对方准备阶段1次，可以从以下效果选择1个发动。 ●从卡组把1只怪兽当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。 ●对方可以把自己的魔法与陷阱区域1张怪兽卡在自身场上特殊召唤。那个场合，再让对方支付那个原本攻击力数值的基本分。 ②：对方场上有原本持有者是自己的效果怪兽特殊召唤的场合，把魔法与陷阱区域的表侧表示的这张卡送去墓地才能发动。从卡组把1只4星以下的怪兽特殊召唤。'),
(23205979, 'Spirit Reaper', '削魂的死灵', '魂を削る死霊', 'Effect Monster', 'Zombie', 'DARK', 3, 300, 200, '①：这张卡不会被战斗破坏。 ②：这张卡直接攻击给与对方战斗伤害的场合发动。对方手卡随机选1张丢弃。 ③：场上的表侧表示的这张卡成为效果的对象的场合破坏。'),
(67957315, 'Spirit Ryu', '灵魂龙', 'スピリット・ドラゴン', 'Effect Monster', 'Dragon', 'WIND', 4, 1000, 1000, '这张卡进行战斗的自己的战斗步骤时，从手卡把1只龙族怪兽丢弃去墓地才能发动。这张卡的攻击力·守备力直到战斗阶段结束时上升1000。'),
(19307353, 'Spirit Sculptor', '魂之造形家', '魂の造形家', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1600, 2100, '这个卡名的效果1回合只能使用1次。 ①：把自己场上1只怪兽解放才能发动。把1只原本攻击力和原本守备力的合计是和解放的怪兽相同的怪兽从卡组加入手卡。'),
(8324284, 'Spirit Shield', '死灵之盾', '死霊の盾', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：对方怪兽的攻击宣言时1次，从自己墓地把1只恶魔族·不死族怪兽除外才能发动。那次攻击无效。 ②：1回合1次，要让卡破坏的效果由对方发动时，从自己墓地把1只恶魔族·不死族怪兽除外才能发动。那个发动无效。 ③：自己·对方的结束阶段，恶魔族·不死族怪兽不在自己场上存在的场合发动。这张卡送去墓地。'),
(42097666, 'Spirit with Eyes of Blue', '青之眼精灵', '青き眼の精霊', 'Link Monster', 'Dragon', 'LIGHT', NULL, 300, NULL, '4星以下的龙族·魔法师族怪兽1只 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡连接召唤的场合才能发动。从卡组选1张「光之灵堂」加入手卡或送去墓地。 ②：只要这张卡在怪兽区域存在，自己不是龙族怪兽不能特殊召唤。 ③：把这张卡解放才能发动。从自己的手卡·墓地把1只「青眼」怪兽特殊召唤。这个效果从墓地特殊召唤的效果怪兽不能攻击，效果无效化。'),
(92394653, 'Spirit''s Invitation', '灵魂的引诱', 'スピリットの誘い', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡的控制者在每次自己的准备阶段支付500基本分。或者不支付500基本分让这张卡破坏。场上表侧表示存在的灵魂怪兽回到自己手卡时，由对方选择对方场上存在的1只怪兽，回到持有者的手卡。'),
(86396750, 'Spiritual Beast Apelio', '精灵兽 亚边狮', '精霊獣 アペライオ', 'Effect Monster', 'Pyro', 'WIND', 4, 1800, 200, '自己对「精灵兽 火狮」1回合只能有1次特殊召唤。 ①：自己·对方回合1次，把自己墓地1张「灵兽」卡除外才能发动。这个回合中自己场上的「灵兽」怪兽的攻击力·守备力上升500。'),
(49885567, 'Spiritual Beast Cannahawk', '精灵兽 神流鹰', '精霊獣 カンナホーク', 'Effect Monster', 'Thunder', 'WIND', 4, 1400, 600, '自己对「精灵兽 雷鹰」1回合只能有1次特殊召唤。 ①：1回合1次，自己主要阶段才能发动。从卡组把1张「灵兽」卡除外。发动后第2次的自己准备阶段，这个效果除外的卡加入手卡。'),
(13890468, 'Spiritual Beast Pettlephin', '精灵兽 别都豚', '精霊獣 ペトルフィン', 'Effect Monster', 'Aqua', 'WIND', 4, NULL, 2000, '自己对「精灵兽 川豚」1回合只能有1次特殊召唤。 ①：1回合1次，从手卡把1张「灵兽」卡除外，以对方场上1张卡为对象才能发动。那张卡回到手卡。'),
(88123329, 'Spiritual Beast Rampengu', '精灵兽 罗梦凤企', '精霊獣 ラムペンタ', 'Effect Monster', 'Beast', 'WIND', 4, 1600, 400, '自己对「精灵兽 心企太」1回合只能有1次特殊召唤。 ①：1回合1次，自己主要阶段才能发动。从额外卡组把1只「灵兽」怪兽除外，和那只怪兽相同种族的1只「灵兽」怪兽从卡组送去墓地。'),
(23623653, 'Spiritual Beast Tamer Lara', '精灵兽使 蕾拉', '精霊獣使い レラ', 'Effect Monster', 'Psychic', 'LIGHT', 1, 100, 2000, '自己对「精灵兽使 蕾拉」1回合只能有1次特殊召唤，那些①②③的效果1回合各能使用1次。 ①：把这张卡从手卡丢弃才能发动。进行手卡1只「灵兽」怪兽的召唤。 ②：自己场上的「灵兽」卡被战斗·效果破坏的场合，可以作为代替把场上·墓地的这张卡除外。 ③：这张卡被除外的场合才能发动。从卡组把「精灵兽使 蕾拉」以外的1只「灵兽」怪兽特殊召唤。'),
(65193366, 'Spiritual Beast Tamer Winda', '精灵兽使 薇茵达', '精霊獣使い ウィンダ', 'Effect Monster', 'Psychic', 'WIND', 4, 1600, 1800, '自己对「精灵兽使 薇茵妲」1回合只能有1次特殊召唤。 ①：这张卡被对方破坏的场合才能发动。从卡组·额外卡组把1只「灵兽」怪兽无视召唤条件特殊召唤。'),
(70156997, 'Spiritual Earth Art - Kurogane', '地灵术－「铁」', '地霊術－「鉄」', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己场上1只地属性怪兽解放，以那只怪兽以外的自己墓地1只4星以下的地属性怪兽为对象才能发动。那只地属性怪兽特殊召唤。'),
(99173029, 'Spiritual Energy Settle Machine', '灵子能固定装置', '霊子エネルギー固定装置', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，灵魂怪兽持续留在场上。自己的结束阶段时丢弃1张手卡，若不丢弃，这张卡破坏。并且，这张卡从场上离开时，在场上存在的表侧表示的灵魂怪兽全部回到持有者的手卡。'),
(28234578, 'Spiritual Entanglement', '灵子纠缠', '霊子もつれ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽直到结束阶段除外。'),
(42945701, 'Spiritual Fire Art - Kurenai', '火灵术－「红」', '火霊術－「紅」', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己场上1只炎属性怪兽解放才能发动。给与对方解放的怪兽的原本攻击力数值的伤害。'),
(69112325, 'Spiritual Forest', '神圣森林', '神聖なる森', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的植物族·兽族·兽战士族怪兽1回合只有1次不会被战斗破坏。这个效果1回合只能适用1次。'),
(5037726, 'Spiritual Light Art - Hijiri', '光灵术－「圣」', '光霊術－「聖」', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己场上1只光属性怪兽解放，以除外的1只自己或者对方的怪兽为对象才能发动。对方可以从手卡把1张陷阱卡给人观看让这个效果无效。没给观看的场合，作为对象的怪兽在自己场上特殊召唤。'),
(78625592, 'Spiritual Swords of Revealing Light', '光之护封灵剑', '光の護封霊剣', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：对方怪兽的攻击宣言时1次，支付1000基本分才能发动。那次攻击无效。 ②：对方回合把墓地的这张卡除外才能发动。这个回合，对方怪兽不能直接攻击。'),
(6540606, 'Spiritual Water Art - Aoi', '水灵术－「葵」', '水霊術－「葵」', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己场上1只水属性怪兽解放才能发动。把对方手卡确认，从那之中选1张卡送去墓地。'),
(50155385, 'Spiritual Whisper', '耳语灵仪鸟', 'スピリチューアル・ウィスパー', 'Effect Monster', 'Winged Beast', 'WIND', 4, 200, 2000, '①：这张卡1回合只有1次不会被战斗破坏。 ②：这张卡灵摆召唤成功时才能发动。从卡组把1只仪式怪兽或者1张仪式魔法卡加入手卡。'),
(79333300, 'Spiritual Wind Art - Miyabi', '风灵术－「雅」', '風霊術－「雅」', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己场上1只风属性怪兽解放，以对方场上1张卡为对象才能发动。那张对方的卡回到持有者卡组最下面。'),
(15866454, 'Spiritualism', '喧闹的邪恶灵', 'ポルターガイスト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以对方场上1张魔法·陷阱卡为对象才能发动。那张对方的卡回到持有者手卡。这张卡的发动和效果不会被无效化。'),
(39765115, 'Splash Capture', '飞溅捕获', 'スプラッシュ・キャプチャー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方超量召唤成功时，把自己墓地2只鱼族怪兽从游戏中除外才能发动。得到那1只超量怪兽的控制权。'),
(59859086, 'Splash Mage', '飞溅闪屏法师', 'スプラッシュ・メイジ', 'Link Monster', 'Cyberse', 'WATER', NULL, 1100, NULL, '电子界族怪兽2只 这个卡名的效果1回合只能使用1次。 ①：以自己墓地1只电子界族怪兽为对象才能发动。那只怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化。这个效果的发动后，直到回合结束时自己不是电子界族怪兽不能特殊召唤。'),
(4290468, 'Splendid Rose', '华丽蔷薇', 'スプレンディッド・ローズ', 'Synchro Monster', 'Plant', 'WIND', 6, 2200, 2000, '调整＋调整以外的怪兽1只以上 1回合1次，可以把自己墓地存在的1只植物族怪兽从游戏中除外，对方场上表侧表示存在的1只怪兽的攻击力直到这个回合的结束阶段时变成一半数值。此外，这张卡攻击的那次战斗阶段中，可以把自己墓地存在的1只植物族怪兽从游戏中除外，这张卡的攻击力直到结束阶段时变成一半数值，只有1次再攻击。'),
(5645210, 'Splendid Venus', '华丽金星', 'The splendid VENUS', 'Effect Monster', 'Fairy', 'LIGHT', 8, 2800, 2400, '①：只要这张卡在怪兽区域存在，天使族以外的场上的怪兽的攻击力·守备力下降500，自己场上的魔法·陷阱卡的效果的发动以及那些发动的效果不会被无效化。'),
(42952160, 'Split Mirror of the Underworld', '冥府的对照镜', '冥府の合わせ鏡', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：对方的攻击·效果让自己受到伤害时才能发动。受到的伤害种类的以下效果适用。 ●战斗：把持有那个数值以下的攻击力的1只怪兽从自己墓地特殊召唤，那次伤害步骤结束后战斗阶段结束。 ●效果：给与对方那个数值2倍的伤害。'),
(44175358, 'Splitting Planarian', '分裂的涡虫', '分裂するプラナリア', 'Effect Monster', 'Insect', 'DARK', 4, 1000, 800, '这个卡名的效果1回合只能使用1次。 ①：把场上的这张卡除外才能发动。从卡组把2只同名的昆虫族·3星怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化，结束阶段除外。'),
(2625939, 'Spool Code', '假脱机代码', 'スプール・コード', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：自己墓地的电子界族怪兽是3只以上的场合，对方怪兽的直接攻击宣言时才能发动。那次攻击无效。那之后，可以在自己场上把最多3只「假脱机衍生物」（电子界族·光·1星·攻/守0）守备表示特殊召唤。这衍生物不能为上级召唤而解放。'),
(42544773, 'Spoon, the Seal of Magistus', '封印之伟魔导士 斯普恩', '封印の魔導士スプーン', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1000, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：可以把这张卡从手卡丢弃，从以下效果选择1个发动。 ●从卡组把「封印之魔导士 斯彭」以外的1只「大贤者」怪兽加入手卡。 ●对方场上1只怪兽的攻击力直到回合结束时变成一半。 ②：把墓地的这张卡除外，以自己场上1只表侧表示怪兽为对象才能发动。从自己的额外卡组·墓地把1只「大贤者」怪兽当作装备魔法卡使用给作为对象的怪兽装备。'),
(11747708, 'Spore', '孢子', 'スポーア', 'Tuner Monster', 'Plant', 'WIND', 1, 400, 800, '这个卡名的效果在决斗中只能使用1次。 ①：这张卡在墓地存在的场合，从自己墓地把这张卡以外的1只植物族怪兽除外才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡的等级上升除外的怪兽的等级数值。'),
(98888032, 'Spore the Fairy Seed', '妖精胞 孢子', '妖精胞スポーア', 'Tuner Monster', 'Plant', 'LIGHT', 1, 400, 800, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡特殊召唤的场合才能发动。这张卡的等级上升最多有自己场上的怪兽数量的数值。 ②：这张卡在墓地存在，自己场上有「古代妖精龙」或者兽族·植物族·天使族的光属性怪兽的其中任意种存在的场合才能发动。这张卡特殊召唤。这个效果的发动后，直到回合结束时自己不是同调怪兽不能从额外卡组特殊召唤。'),
(76145933, 'Spright Blue', '电光闪灵・蓝精', 'スプライト・ブルー', 'Effect Monster', 'Thunder', 'DARK', 2, 1100, 1000, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：自己场上有2星或2阶的怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡特殊召唤的场合才能发动。从卡组把「卫星闪灵·蓝色喷流灵」以外的1只「卫星闪灵」怪兽加入手卡。'),
(2311090, 'Spright Carrot', '电光闪灵・萝卜精', 'スプライト・キャロット', 'Effect Monster', 'Thunder', 'FIRE', 2, 1000, 1900, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：自己场上有2星或连接2的怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：对方把魔法·陷阱卡的效果发动时，把自己场上1只其他的2星·2阶·连接2的怪兽解放才能发动。那个效果无效。把2阶或连接2的怪兽解放发动的场合，可以再把那张无效的卡破坏。'),
(68250822, 'Spright Double Cross', '电光闪灵・双交叉击', 'スプライト・ダブルクロス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以以自己或对方的场上·墓地1只怪兽为对象，从以下效果选择1个发动。 ●把作为对象的怪兽作为自己场上1只2阶怪兽的超量素材。 ●作为对象的对方场上的怪兽在作为自己场上的连接2怪兽所连接区的自己场上放置得到控制权。 ●作为对象的墓地的怪兽在作为自己场上的连接2怪兽所连接区的自己场上特殊召唤。'),
(27381364, 'Spright Elf', '电光闪灵・精灵', 'スプライト・エルフ', 'Link Monster', 'Thunder', 'FIRE', NULL, 1400, NULL, '包含2星·2阶·连接2的怪兽在内的怪兽2只 这张卡在连接召唤的回合不能作为连接素材。这个卡名的②的效果1回合只能使用1次。 ①：对方不能把这张卡所连接区的怪兽作为效果的对象。 ②：自己·对方的主要阶段，以自己墓地1只2星怪兽为对象才能发动（对方场上有怪兽存在的场合，也能作为代替以1只2阶或者连接2的怪兽为对象）。那只怪兽特殊召唤。'),
(42431833, 'Spright Gamma Burst', '电光闪灵・伽马暴', 'スプライト・ガンマ・バースト', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：场上的全部2星·2阶·连接2的怪兽的攻击力·守备力直到回合结束时上升1400。 ②：自己主要阶段把墓地的这张卡除外，以自己场上1只2星·2阶·连接2的怪兽为对象才能发动。那只怪兽的攻击力直到对方回合结束时上升1400。'),
(13533678, 'Spright Jet', '电光闪灵・喷流', 'スプライト・ジェット', 'Effect Monster', 'Thunder', 'DARK', 2, 1300, 700, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：自己场上有2星或2阶的怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡特殊召唤的场合才能发动。从卡组把1张「卫星闪灵」魔法·陷阱卡加入手卡。'),
(49928686, 'Spright Pixies', '电光闪灵・皮克精', 'スプライト・ピクシーズ', 'Effect Monster', 'Thunder', 'DARK', 2, 1400, 1400, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：自己场上有2星或者2阶的怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：其他的自己的2星·2阶·连接2的怪兽和对方怪兽进行战斗的伤害计算时，把手卡·场上的这张卡送去墓地才能发动。那只自己怪兽的攻击力·守备力直到回合结束时上升那只对方怪兽的攻击力数值。'),
(75922381, 'Spright Red', '电光闪灵・红精', 'スプライト・レッド', 'Effect Monster', 'Thunder', 'FIRE', 2, 1200, 1800, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：自己场上有2星或连接2的怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：对方把怪兽的效果发动时，把自己场上1只其他的2星·2阶·连接2的怪兽解放才能发动。那个效果无效。把2阶或连接2的怪兽解放发动的场合，可以再把那只无效的怪兽破坏。'),
(88836438, 'Spright Smashers', '电光闪灵・粉碎者乱斗', 'スプライト・スマッシャーズ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以从自己的手卡·墓地把「护宝炮妖」卡、「兽带斗神」卡、「卫星闪灵」卡的其中1张除外，从以下效果选择1个发动。 ●从卡组把1只「护宝炮妖」怪兽特殊召唤。 ●从自己墓地把1只「兽带斗神」怪兽特殊召唤。 ●自己场上1只2星·2阶·连接2的怪兽和对方场上1张卡除外。'),
(72329844, 'Spright Sprind', '电光闪灵・猎宝械种', 'スプライト・スプリンド', 'Link Monster', 'Thunder', 'FIRE', NULL, 1400, NULL, '包含2星·2阶·连接2的怪兽在内的怪兽2只 这张卡在连接召唤的回合不能作为连接素材。这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡连接召唤成功的场合才能发动。从卡组把1只2星怪兽送去墓地。 ②：这张卡在怪兽区域存在的状态，怪兽特殊召唤的场合，把自己场上1个超量素材取除，以场上1只怪兽为对象才能发动。那只怪兽回到手卡。'),
(15443125, 'Spright Starter', '电光闪灵・启辉器', 'スプライト・スターター', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把1只「卫星闪灵」怪兽特殊召唤，自己失去那只怪兽的原本攻击力数值的基本分。这张卡的发动后，直到回合结束时自己不是2星·2阶·连接2的怪兽不能特殊召唤。'),
(1906812, 'Sprind the Irondash Dragon', '铁驱龙 猎宝械种', '鉄駆竜スプリンド', 'Fusion Monster', 'Machine', 'DARK', 8, 2500, 2000, '「阿不思的落胤」＋这个回合特殊召唤的效果怪兽 这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。自己场上的这张卡的位置向其他的自己的主要怪兽区域移动。那之后，可以把和移动过的这张卡相同纵列的其他的表侧表示卡全部破坏。 ②：这张卡被送去墓地的回合的结束阶段才能发动。从卡组选1只「护宝炮妖」怪兽或「阿不思的落胤」加入手卡或特殊召唤。'),
(60600821, 'Spring', '春', '春', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：1回合1次，可以发动。指定没有使用的自己的主要怪兽区域任意数量，那个数量的四季指示物给这张卡放置。那些区域在这张卡存在期间不能使用。 ②：自己场上的怪兽的攻击力上升这张卡的四季指示物数量×400。 ③：对方结束阶段才能发动。可以放置四季指示物的1张场地魔法卡从卡组到自己场上表侧表示放置（这张卡的四季指示物移给那张卡）。那张卡的效果在这个回合不能发动。'),
(94425169, 'Spring of Rebirth', '元素之泉', 'エレメントの泉', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '场上的怪兽回到持有者手卡的场合，每1次自己回复500基本分。'),
(10584050, 'Springans Blast!', '守宝团・爆破！', 'スプリガンズ・ブラスト！', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「护宝炮妖」怪兽存在的场合，指定对方的主要怪兽区域1处才能发动（自己场上有需以「阿不思的落胤」为融合素材的融合怪兽存在的场合，这个效果指定的区域可以变成2处）。那个区域有表侧表示怪兽存在的场合，那只怪兽在这个回合不能直接攻击，效果无效化。那个区域没有怪兽存在的场合，这个回合，指定的区域不能使用。'),
(7496001, 'Springans Booty', '守宝团・战利品', 'スプリガンズ・ブーティー', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上的表侧表示的超量怪兽因效果从场上离开的场合，以对方场上1只效果怪兽为对象才能发动。这个回合，那只效果怪兽不能把场上发动的效果发动。 ②：把魔法与陷阱区域的表侧表示的这张卡送去墓地才能发动。从自己的卡组·墓地把1张「大沙海 黄金戈尔工达」发动。'),
(83203672, 'Springans Branga', '守宝团・庞哥', 'スプリガンズ・バンガー', 'Effect Monster', 'Machine', 'FIRE', 8, 500, 2500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡·场上·墓地存在的场合，以自己场上1只「护宝炮妖」超量怪兽为对象才能发动。把这张卡作为那只怪兽的超量素材。 ②：从自己墓地把「护宝炮妖·爆竹」以外的1只「护宝炮妖」怪兽和这张卡除外才能发动。从卡组把1张「护宝炮妖」卡加入手卡。'),
(67436768, 'Springans Brothers', '守宝团・兄弟', 'スプリガンズ・ブラザーズ', 'Effect Monster', 'Machine', 'FIRE', 4, 300, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡从手卡·卡组送去墓地的场合，以「护宝炮妖兄弟」以外的自己墓地1只「护宝炮妖」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。 ②：这张卡在手卡·场上·墓地存在的场合，以自己场上1只「护宝炮妖」超量怪兽为对象才能发动。把这张卡作为那只怪兽的超量素材。'),
(83199011, 'Springans Call!', '守宝团・警报！', 'スプリガンズ・コール！', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己墓地1只「护宝炮妖」怪兽或者「阿不思的落胤」为对象才能发动。那只怪兽特殊召唤。 ②：从自己墓地把1只融合怪兽和这个回合没有送去墓地的这张卡除外，以自己场上1只「护宝炮妖」超量怪兽为对象才能发动。从额外卡组把以「阿不思的落胤」为融合素材的1只融合怪兽作为那只怪兽的超量素材。'),
(29601381, 'Springans Captain Sargas', '守宝团・舰长 飒嘉斯', 'スプリガンズ・キャプテン サルガス', 'Effect Monster', 'Machine', 'FIRE', 8, 1500, 2800, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡·场上·墓地存在的场合，以自己场上1只「护宝炮妖」超量怪兽为对象才能发动。把这张卡作为那只怪兽的超量素材。 ②：对方回合，把自己场上1个超量素材取除，以场上1张表侧表示卡为对象才能发动。那张卡破坏。 ③：持有这张卡作为素材中的「护宝炮妖」超量怪兽得到以下效果。 ●这张卡的攻击力上升500。'),
(25415161, 'Springans Interluder', '守宝团・途中插曲', 'スプリガンズ・インタールーダー', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：对方把卡的效果发动时才能发动。自己场上1只「护宝炮妖」超量怪兽回到额外卡组。那之后，从以下效果选1个适用。 ●那个发动的效果无效。 ●从自己墓地把1只8星怪兽特殊召唤。 ②：自己场上的表侧表示的超量怪兽因效果从场上离开的场合才能发动。对方场上的全部怪兽的攻击力直到回合结束时下降1000。'),
(45484331, 'Springans Kitt', '守宝团・姬特', 'スプリガンズ・キット', 'Effect Monster', 'Beast', 'DARK', 4, 1700, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：需以「阿不思的落胤」为融合素材的融合怪兽在自己的场上或墓地存在的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。自己的卡组·墓地·除外状态的1张「烙印」魔法·陷阱卡加入手卡。那之后，选自己1张手卡回到卡组最下面。'),
(48285768, 'Springans Merrymaker', '守宝团・气氛组', 'スプリガンズ・メリーメイカー', 'XYZ Monster', 'Machine', 'FIRE', 4, 1100, 2000, '4星怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡从额外卡组特殊召唤的场合才能发动。从卡组把1只「护宝炮妖」怪兽送去墓地。 ②：对方的主要阶段以及战斗阶段才能发动。这张卡直到结束阶段除外。把持有超量素材2个以上的这张卡除外的场合，可以再从额外卡组把以「阿不思的落胤」为融合素材的1只融合怪兽送去墓地。'),
(56818977, 'Springans Pedor', '守宝团・佩德', 'スプリガンズ・ピード', 'Effect Monster', 'Machine', 'FIRE', 4, NULL, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡解放，以「护宝炮妖·鱼雷」以外的自己墓地1只「护宝炮妖」怪兽为对象才能发动。那只怪兽特殊召唤。 ②：这张卡在手卡·场上·墓地存在的场合，以自己场上1只「护宝炮妖」超量怪兽为对象才能发动。把这张卡作为那只怪兽的超量素材。'),
(20424878, 'Springans Rockey', '守宝团・洛疾', 'スプリガンズ・ロッキー', 'Effect Monster', 'Machine', 'FIRE', 4, 1800, 800, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合，以「护宝炮妖·小火箭」以外的自己墓地1只「护宝炮妖」怪兽或者1张「大沙海 黄金戈尔工达」为对象才能发动。那张卡加入手卡。 ②：这张卡在手卡·场上·墓地存在的场合，以自己场上1只「护宝炮妖」超量怪兽为对象才能发动。把这张卡作为那只怪兽的超量素材。'),
(62941499, 'Springans Ship - Exblowrer', '守宝团・乘风舰 寻宝盈天号', 'スプリガンズ・シップ エクスブロウラー', 'XYZ Monster', 'Machine', 'FIRE', 8, 1600, 2500, '8星怪兽×2只以上 这个卡名的①②的效果1回合各能使用1次。 ①：指定对方的怪兽区域或者魔法与陷阱区域1处才能发动。这张卡的超量素材任意数量取除，把指定的区域以及那些前面·后面·相邻的区域（怪兽区域·魔法与陷阱区域）存在的那个数量的对方的卡破坏。 ②：对方的主要阶段以及战斗阶段才能发动。这张卡直到结束阶段除外。'),
(23499963, 'Springans Watch', '守宝团・观察', 'スプリガンズ・ウォッチ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把1张「大沙海 黄金戈尔工达」加入手卡。自己的场地区域有「大沙海 黄金戈尔工达」存在的场合，可以作为代替让以下效果适用。 ●从卡组把1只「护宝炮妖」怪兽加入手卡，从卡组把1只「护宝炮妖」怪兽送去墓地。'),
(37626500, 'Sprite''s Blessing', '精灵的祝福', '精霊の祝福', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '光属性仪式怪兽的降临必需。 ①：等级合计直到变成和仪式召唤的怪兽相同为止，把自己的手卡·场上的怪兽解放，从手卡把1只光属性仪式怪兽仪式召唤。'),
(21088856, 'Spy-C-Spy', '华丽的密探-C', '華麗なる密偵－C', 'Effect Monster', 'Warrior', 'FIRE', 3, 1200, 1300, '①：这张卡召唤成功的场合发动。从对方的额外卡组随机1张确认。攻击力2000以上的怪兽的场合，这张卡的攻击力上升1000。攻击力未满2000的怪兽的场合，自己基本分回复那个攻击力的数值。'),
(80637190, 'Spyder Spider', '间谍蜘蛛', 'スパイダー・スパイダー', 'Effect Monster', 'Insect', 'EARTH', 4, 1500, 1000, '这张卡战斗破坏对方场上守备表示存在的怪兽的场合，可以选择自己墓地存在的1只4星以下的昆虫族怪兽特殊召唤。'),
(94096018, 'SPYGAL Misty', '秘辣谍－迷雾女郎', 'SPYGAL－ミスティ', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1500, 1600, '①：这张卡召唤·特殊召唤成功的场合，宣言卡的种类（怪兽·魔法·陷阱）才能发动。对方卡组最上面的卡给双方确认，宣言的种类的卡的场合，自己从卡组抽1张。 ②：1回合1次，以自己场上1只「秘旋谍-花公子」和对方场上1只怪兽为对象才能发动。那2只怪兽回到持有者手卡。这个效果在对方回合也能发动。'),
(88124568, 'SPYRAL Double Agent', '秘旋谍－双重伪装', 'SPYRAL－ダブルフェイク', 'Effect Monster', 'Fiend', 'LIGHT', 4, 1400, 600, '这个卡名的①的效果1回合只能使用1次。 ①：自己的场上或墓地有「秘旋谍」卡存在的场合才能发动。这张卡从手卡往对方场上守备表示特殊召唤。那之后，双方卡组最上面的卡给双方确认。这个效果特殊召唤的这张卡不能解放，也不能作为融合·同调·超量·连接召唤的素材。 ②：场上的「秘旋谍」怪兽的攻击力上升500，「秘旋谍-花公子」可以直接攻击。'),
(1322368, 'SPYRAL Double Helix', '秘旋谍－双螺旋', 'SPYRAL－ザ・ダブルヘリックス', 'Link Monster', 'Warrior', 'EARTH', NULL, 1900, NULL, '「秘旋谍」怪兽2只 这个卡名的②的效果1回合只能使用1次。 ①：这张卡的卡名只要在场上·墓地存在当作「秘旋谍-花公子」使用。 ②：宣言卡的种类（怪兽·魔法·陷阱）才能发动。对方卡组最上面的卡给双方确认，宣言的种类的卡的场合，从自己的卡组·墓地选1只「秘旋谍」怪兽加入手卡或在作为这张卡所连接区的自己场上特殊召唤。'),
(30979619, 'SPYRAL GEAR - Big Red', '秘旋谍装备－大红', 'SPYRAL GEAR－ビッグ・レッド', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己墓地1只「秘旋谍」怪兽为对象才能把这张卡发动。那只怪兽特殊召唤，把这张卡装备。 ②：装备怪兽不会被战斗破坏。'),
(4474060, 'SPYRAL GEAR - Drone', '秘旋谍装备－无人机', 'SPYRAL GEAR－ドローン', 'Effect Monster', 'Machine', 'WIND', 1, 100, 100, '①：这张卡召唤·特殊召唤成功的场合才能发动。从对方卡组上面把3张卡确认，用喜欢的顺序回到卡组上面。 ②：把这张卡解放，以自己场上1只「秘旋谍」怪兽为对象才能发动。那只怪兽的攻击力上升对方场上的卡数量×500。这个效果在对方回合也能发动。 ③：从自己墓地把这张卡和1张「秘旋谍」卡除外，以自己墓地1只「秘旋谍-花公子」为对象才能发动。那张卡加入手卡。'),
(73828446, 'SPYRAL GEAR - Fully Armed', '秘旋谍装备－特级臂甲', 'SPYRAL GEAR－エクストラアームズ', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '「秘旋谍-花公子」才能装备。 ①：装备怪兽的攻击力上升1000。 ②：装备怪兽战斗破坏对方怪兽的场合才能发动。选对方场上1张卡，那张卡和破坏的怪兽除外。 ③：场上的表侧表示的这张卡被破坏送去墓地时，以自己墓地1只「秘旋谍-花公子」为对象才能发动。那只怪兽特殊召唤。'),
(37433748, 'SPYRAL GEAR - Last Resort', '秘旋谍装备－绝地胜机', 'SPYRAL GEAR－ラスト・リゾート', 'Effect Monster', 'Machine', 'EARTH', 4, 1000, 1000, '①：自己主要阶段以自己场上1只「秘旋谍」怪兽为对象才能发动。从自己的手卡·场上把这只怪兽当作装备卡使用给那只自己怪兽装备。装备怪兽不会被战斗·效果破坏，不会成为对方的效果的对象。 ②：1回合1次，这张卡的效果让这张卡装备中的场合，把这张卡以外的自己场上1张卡送去墓地才能发动。这个回合，装备怪兽可以直接攻击。'),
(53989821, 'SPYRAL GEAR - Utility Wire', '秘旋谍装备－万能绳索', 'SPYRAL GEAR－マルチワイヤー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「秘旋谍-花公子」存在的场合，以对方场上1张表侧表示的卡为对象才能发动。那张卡回到持有者卡组最上面。'),
(91258852, 'SPYRAL Master Plan', '秘旋谍－高雅', 'SPYRAL－グレース', 'Effect Monster', 'Spellcaster', 'DARK', 7, 1200, 2800, '这个卡名的②的效果1回合只能使用1次。 ①：1回合1次，自己主要阶段才能发动。从卡组把1张「秘旋谍任务」卡加入手卡。 ②：这张卡从场上送去墓地的场合才能发动。从卡组把「秘旋谍-高雅女士」以外的1只「秘旋谍」怪兽和1张「秘旋谍的秘密胜地」加入手卡。'),
(27642961, 'SPYRAL MISSION - Assault', '秘旋谍任务－强袭', 'SPYRAL MISSION－強襲', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡发动后，第3次的自己结束阶段破坏。 ①：1回合1次，自己的「秘旋谍」怪兽战斗破坏怪兽的场合或者自己场上的「秘旋谍」怪兽的效果把场上的卡破坏的场合才能发动。自己从卡组抽1张。 ②：把墓地的这张卡除外才能发动。从手卡把1只「秘旋谍」怪兽特殊召唤。'),
(39373426, 'SPYRAL MISSION - Recapture', '秘旋谍任务－夺回', 'SPYRAL MISSION－奪還', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡发动后，第3次的自己结束阶段破坏。 ①：1回合1次，自己场上有「秘旋谍」怪兽特殊召唤的场合，以对方场上1只怪兽为对象才能发动。那只怪兽的控制权直到结束阶段得到。这个效果得到控制权的怪兽在这个回合不能直接攻击。 ②：自己场上的「秘旋谍」怪兽被战斗·效果破坏的场合，可以作为那1只破坏的怪兽的代替而把墓地的这张卡除外。'),
(9212051, 'SPYRAL MISSION - Rescue', '秘旋谍任务－援救', 'SPYRAL MISSION－救出', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡发动后，第3次的自己结束阶段破坏。 ①：「秘旋谍任务-救出」在自己场上只能有1张表侧表示存在。 ②：1回合1次，以自己墓地1只「秘旋谍」怪兽为对象才能发动。那只怪兽加入手卡。 ③：把墓地的这张卡除外，以自己墓地1只「秘旋谍」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(78080961, 'SPYRAL Quik-Fix', '秘旋谍－天才', 'SPYRAL－ジーニアス', 'Effect Monster', 'Machine', 'EARTH', 1, 500, 400, '①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1张「秘旋谍装备」卡加入手卡。 ②：这张卡在墓地存在，自己场上有「秘旋谍-花公子」存在的场合丢弃1张手卡才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(54631665, 'SPYRAL Resort', '秘旋谍胜地', 'SPYRAL RESORT', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这张卡的控制者在每次自己结束阶段让自己墓地1只怪兽回到卡组。或者不回到卡组让这张卡破坏。 ①：只要这张卡在场地区域存在，这张卡以外的自己场上的「秘旋谍」卡不会成为对方的效果的对象。 ②：1回合1次，自己主要阶段才能发动。从卡组把1只「秘旋谍」怪兽加入手卡。'),
(35699, 'SPYRAL Sleeper', '秘旋谍－暴涡', 'SPYRAL－ボルテックス', 'Effect Monster', 'Fiend', 'LIGHT', 8, 2800, 1200, '这张卡不能通常召唤。把自己墓地3张「秘旋谍」卡除外的场合才能特殊召唤。 ①：1回合1次，以自己场上1张「秘旋谍」卡和对方场上最多2张卡为对象才能发动。那些卡破坏。这个效果在对方回合也能发动。 ②：场上的这张卡被战斗·效果破坏送去墓地的场合发动。自己场上的卡全部破坏，从自己的手卡·卡组·墓地选1只「秘旋谍-花公子」特殊召唤。'),
(41091257, 'SPYRAL Super Agent', '秘旋谍－花花公子', 'SPYRAL－ダンディ', 'Effect Monster', 'Warrior', 'EARTH', 4, 1900, 1200, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在的场合，宣言卡的种类（怪兽·魔法·陷阱）才能发动。对方卡组最上面的卡给双方确认，宣言的种类的卡的场合，这张卡从手卡特殊召唤。 ②：这张卡用「秘旋谍」卡的效果特殊召唤成功的场合，以对方场上1张魔法·陷阱卡为对象才能发动。那张卡破坏。'),
(20584712, 'SPYRAL Tough', '秘旋谍－硬汉', 'SPYRAL－タフネス', 'Effect Monster', 'Warrior', 'WIND', 4, 1900, 1500, '①：这张卡的卡名只要在场上·墓地存在当作「秘旋谍-花公子」使用。 ②：1回合1次，宣言卡的种类（怪兽·魔法·陷阱），以对方场上1张卡为对象才能发动。对方卡组最上面的卡给双方确认，宣言的种类的卡的场合，作为对象的卡破坏。'),
(38783169, 'Squeaknight', '调整鼠骑士', 'チューン・ナイト', 'Union Effect Monster', 'Warrior', 'FIRE', 1, 500, 500, '①：这张卡特殊召唤成功的场合才能发动。这个回合，这张卡当作调整使用。这个效果的发动后，直到回合结束时自己只能有1次从额外卡组把怪兽特殊召唤。 ②：1回合1次，可以从以下效果选择1个发动。 ●以自己场上1只表侧表示怪兽为对象，把这张卡当作装备卡使用给那只怪兽装备。装备怪兽被战斗·效果破坏的场合，作为代替把这张卡破坏。 ●装备的这张卡特殊召唤。'),
(54458867, 'Squib Draw', '炸膛抽牌', 'スクイブ・ドロー', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只「弹丸」怪兽为对象才能发动。那只怪兽破坏，自己从卡组抽2张。'),
(65500515, 'Squirt Squid', '隅乌贼', '隅烏賊', 'Effect Monster', 'Aqua', 'WATER', 2, NULL, 1800, '①：1回合1次，这张卡被选择作为对方怪兽的攻击对象时才能发动。自己场上的这张卡的位置向其他的自己的主要怪兽区域移动。那之后，在自己场上把1只「乌贼墨衍生物」（水族·水·2星·攻?/守0）特殊召唤。这衍生物的攻击力变成和那只对方怪兽的攻击力相同。 ②：持有这张卡的守备力以下的攻击力的对方怪兽不能选择主要怪兽区域的右端或左端存在的这张卡作为攻击对象。'),
(21175632, 'St. Joan', '圣女 贞德', '聖女ジャンヌ', 'Fusion Monster', 'Fairy', 'LIGHT', 7, 2800, 2000, '「大慈大悲的修女」＋「堕天使 玛丽」'),
(9523599, 'Stack Reviver', '堆栈复活者', 'スタック・リバイバー', 'Effect Monster', 'Cyberse', 'DARK', 2, 100, 600, '这个卡名的效果在决斗中只能使用1次。 ①：这张卡为素材作连接召唤的场合，以这张卡以外的自己墓地1只作为那次连接召唤的素材的4星以下的电子界族怪兽为对象才能发动。那只怪兽守备表示特殊召唤。'),
(16598965, 'Stained Glass of Light & Dark', '圣邪之花窗玻璃', '聖邪のステンドグラス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上的效果怪兽的种族的以下效果各能适用。 ●天使族：自己抽3张。那之后，选2张手卡用喜欢的顺序回到卡组下面。 ●恶魔族：对方抽1张。那之后，对方把手卡随机1张丢弃。并且对方在有手卡的场合再选1张丢弃。'),
(19671102, 'Stairs of Mail', '奇迹螺旋阶梯', 'メールの階段', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：自己主要阶段才能把这个效果发动。从手卡丢弃1张「廷达魔三角」卡，从以下效果选1个适用。这个回合，和这个效果丢弃的卡同名的卡不能用自己的「奇迹螺旋阶梯」的效果丢弃。 ●选自己场上1只里侧守备表示怪兽变成表侧攻击表示。 ●选自己场上1只表侧攻击表示怪兽变成里侧守备表示。'),
(22555834, 'Stairway to a Fabled Realm', '魔轰神界之阶', '魔轟神界の階', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的②的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，可以从卡组把1只「魔轰神」怪兽送去墓地。 ②：以自己墓地1只「魔轰神」怪兽为对象才能发动。选自己2张手卡丢弃，作为对象的怪兽加入手卡。 ③：自己手卡比对方少的场合，自己的「魔轰神」怪兽的攻击力只在向对方怪兽攻击的伤害计算时上升双方手卡数量差×200。'),
(54562327, 'Stake your Soul!', '赌上你的灵魂！', 'Stake Your Soul！', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把手卡1只怪兽给对方观看才能发动。和给人观看的怪兽是卡名不同并是属性相同的1只「征服斗魂」怪兽从卡组特殊召唤。这个效果特殊召唤的怪兽在结束阶段回到手卡。'),
(86060749, 'Stall Turn', '失速转向', 'ストールターン', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：可以从自己卡组上面把3张卡里侧表示除外把以下效果发动。 ●要让怪兽的召唤·反转召唤·特殊召唤无效的怪兽的效果·魔法·陷阱卡发动时才能发动。那个发动无效，那张卡回到持有者卡组。 ●要让魔法·陷阱卡的发动无效的怪兽的效果·魔法·陷阱卡发动时才能发动。那个发动无效，那张卡回到持有者卡组。'),
(81385346, 'Stamping Destruction', '粉碎践踏', 'スタンピング・クラッシュ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己的场上有表侧表示的龙族怪兽存在时才能发动。破坏场上的1张魔法·陷阱卡，给与那张被破坏的卡的控制者500分的伤害。'),
(49154689, 'Stand In', '替身演员', 'スタンド・イン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把自己场上1只怪兽解放，以原本的种族·属性是和那只怪兽相同的对方墓地1只怪兽为对象才能发动。那只怪兽在自己场上特殊召唤。'),
(41371602, 'Stand Up Centur-Ion!', '站起来吧・百夫骑士！', 'スタンドアップ・センチュリオン！', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的②③的效果1回合各能使用1次。 ①：只要自己场上有「百夫长骑士」怪兽卡存在，这张卡不会被对方的效果破坏。 ②：这张卡发动的回合的自己主要阶段，把1张手卡送去墓地才能发动。从卡组把1只「百夫长骑士」怪兽当作永续陷阱卡使用在自己的魔法与陷阱区域表侧表示放置。 ③：怪兽特殊召唤的场合才能发动。用包含「百夫长骑士」怪兽的自己场上的怪兽为素材进行同调召唤。'),
(65384188, 'Stand-Off', '实力伯仲', '実力伯仲', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己以及对方场上表侧攻击表示存在的效果怪兽各1只才能发动。选择的2只怪兽的效果无效。那之后，只要选择的2只怪兽在场上表侧攻击表示存在，选择的怪兽不会被战斗破坏，不受这张卡以外的卡的效果影响，也不能作攻击和表示形式的变更。'),
(67196946, 'Star Blast', '星级爆破', 'スター・ブラスト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '支付500的倍数的基本分才能发动。选自己手卡或者自己场上表侧表示存在的1只怪兽，那只怪兽的等级直到结束阶段时下降支付的基本分每500分1星。'),
(8201910, 'Star Boy', '海星小子', 'スター・ボーイ', 'Effect Monster', 'Aqua', 'WATER', 2, 550, 500, '只要这张卡在场上表侧表示存在，全部水属性的怪兽攻击力上升500。炎属性的怪兽攻击力下降400。'),
(63485233, 'Star Changer', '星级变化', 'スター・チェンジャー', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '选择场上表侧表示存在的1只怪兽，从以下效果选择1个发动。 ●那只怪兽的等级上升1星。 ●那只怪兽的等级下降1星。'),
(24610207, 'Star Drawing', '画星宝宝', 'アステル・ドローン', 'Effect Monster', 'Spellcaster', 'EARTH', 4, 1600, 1000, '①：把这张卡在超量召唤使用的场合，可以把这张卡的等级当作5星使用。 ②：场上的这张卡为素材作超量召唤的怪兽得到以下效果。 ●这次超量召唤成功的场合发动。自己从卡组抽1张。'),
(41517789, 'Star Eater', '星态龙', '星態龍', 'Synchro Monster', 'Dragon', 'LIGHT', 11, 3200, 2800, '调整＋调整以外的怪兽1只以上 这张卡不用同调召唤不能特殊召唤。 ①：这张卡的同调召唤不会被无效化。 ②：在这张卡的同调召唤成功时双方不能把魔法·陷阱·怪兽的效果发动。 ③：这张卡攻击的场合，直到伤害步骤结束时不受其他卡的效果影响。'),
(43661068, 'Star Light, Star Bright', '望星许愿', '星に願いを', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只怪兽发动。持有和选择的怪兽相同攻击力或者相同守备力的自己场上的怪兽的等级直到结束阶段时变成和选择的怪兽相同。'),
(49407319, 'Star Mine', '烟花爆爆', 'スター・マイン', 'Synchro Monster', 'Pyro', 'FIRE', 4, 2000, 200, '调整＋调整以外的怪兽1只以上 自己对「速射连发烟花」1回合只能有1次特殊召唤。 ①：这张卡被对方怪兽的攻击或者对方的效果破坏的场合发动。自己受到2000伤害。那之后，给与对方2000伤害。 ②：这张卡的相邻的怪兽区域存在的怪兽被对方怪兽的攻击或者对方的效果破坏的场合发动。这张卡破坏，自己受到2000伤害。那之后，给与对方2000伤害。'),
(74850403, 'Star Pendulumgraph', '星霜的灵摆读阵', '星霜のペンデュラムグラフ', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在魔法与陷阱区域存在，对方不能把自己场上的魔法师族怪兽作为魔法卡的效果的对象。 ②：自己的怪兽区域·灵摆区域的表侧表示的「魔术师」灵摆怪兽卡从场上离开的场合发动。从卡组把1只「魔术师」灵摆怪兽加入手卡。'),
(76500786, 'Star Power!!', '一曲集中', '一曲集中', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己的连接怪兽和对方怪兽进行战斗的伤害计算时才能发动。那只自己怪兽的攻击力只在那次伤害计算时上升那所连接区的怪兽的等级·阶级的合计×400。'),
(84433129, 'Star Ryzeal', '星气・雷热涡炉', 'スター・ライゼオル', 'Effect Monster', 'Pyro', 'LIGHT', 4, 1800, NULL, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：这张卡可以把自己场上1个超量素材取除，从手卡特殊召唤。这个方法特殊召唤过的回合，自己不是4阶超量怪兽不能从额外卡组特殊召唤。 ②：这张卡特殊召唤的场合才能发动。从卡组把1张「雷火沸动」魔法·陷阱卡在自己场上盖放。'),
(44273680, 'Star Seraph Sage', '光天使 天书', '光天使ブックス', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1600, 1400, '1回合1次，把手卡1张魔法卡送去墓地才能发动。从手卡把1只名字带有「光天使」的怪兽特殊召唤。'),
(64726269, 'Star Seraph Scale', '光天使 天秤', '光天使スケール', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1500, 900, '①：这张卡特殊召唤成功时才能发动。从手卡把1只「光天使」怪兽特殊召唤。那之后，可以选自己墓地1只光属性怪兽在卡组最上面放置。 ②：包含场上的这张卡的怪兽3只以上为素材作超量召唤的怪兽得到以下效果。 ●只要持有超量素材的这张卡在怪兽区域存在，每次自己或者对方从手卡把怪兽特殊召唤，自己从卡组抽1张。这个效果1回合只能适用1次。'),
(38331564, 'Star Seraph Scepter', '光天使 天杖', '光天使セプター', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1800, 400, '①：这张卡召唤·特殊召唤成功时才能发动。从卡组把「光天使 天杖」以外的1只「光天使」怪兽加入手卡。 ②：包含场上的这张卡的怪兽3只以上为素材作超量召唤的怪兽得到以下效果。 ●这次超量召唤成功时，以这张卡以外的场上1张卡为对象才能发动。那张卡破坏，自己可以从卡组抽1张。'),
(8875971, 'Star Seraph Scout', '光天使 天翼', '光天使ウィングス', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1200, 1800, '这张卡召唤成功时，可以从手卡把1只名字带有「光天使」的怪兽特殊召唤。'),
(91110378, 'Star Seraph Sovereignty', '光天使 天座', '光天使スローネ', 'Effect Monster', 'Fairy', 'LIGHT', 4, 800, 2000, '把这张卡作为超量召唤的素材的场合，不是以怪兽3只以上为素材的超量召唤不能使用。 ①：自己对「光天使」怪兽的召唤·特殊召唤成功的场合才能发动。这张卡从手卡特殊召唤，自己从卡组抽1张。那张抽到的卡是「光天使」怪兽的场合，可以把那只怪兽特殊召唤。'),
(70668285, 'Star Seraph Sword', '光天使 天剑', '光天使ソード', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1400, 1000, '1回合1次，把手卡1只名字带有「光天使」的怪兽送去墓地才能发动。这张卡的攻击力直到结束阶段时上升送去墓地的怪兽的原本攻击力数值。'),
(70391588, 'Star Siphon', '星食-等级攀升-', '星蝕－レベル・クライム－', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '同调怪兽特殊召唤时，选择那1只怪兽发动。在自己场上把1只「星食衍生物」（魔法师族·暗·1星·攻/守0）特殊召唤。这衍生物的等级变成和选择的怪兽相同的等级，选择的怪兽的等级变成1星。'),
(34244455, 'Star Staring Starling', '星向鸟', '星向鳥', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1000, 1500, '①：这张卡只要在主要怪兽区域存在，得到那个位置的以下效果。 ●左端：这张卡的等级上升4星。 ●右端：这张卡的等级上升3星。 ●中央：这张卡的等级上升2星。 ●那以外：这张卡的等级上升1星。'),
(97792247, 'Stardust Assault Warrior', '星尘冲锋战士', 'スターダスト・アサルト・ウォリアー', 'Synchro Monster', 'Warrior', 'WIND', 6, 2100, 1200, '调整＋调整以外的怪兽1只以上 「星尘强袭战士」的①的效果1回合只能使用1次。 ①：这张卡同调召唤成功时，自己场上没有其他怪兽存在的场合以自己墓地1只「废品」怪兽为对象才能发动。那只怪兽特殊召唤。 ②：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。'),
(64880894, 'Stardust Charge Warrior', '星尘充能战士', 'スターダスト・チャージ・ウォリアー', 'Synchro Monster', 'Warrior', 'WIND', 6, 2000, 1300, '调整＋调整以外的怪兽1只以上 这个卡名的①的效果1回合只能使用1次。 ①：这张卡同调召唤时才能发动。自己抽1张。 ②：这张卡可以向特殊召唤的对方怪兽全部各作1次攻击。'),
(89474727, 'Stardust Chronicle Spark Dragon', '真闪珖龙 星尘编年史', '真閃珖竜 スターダスト・クロニクル', 'Synchro Monster', 'Dragon', 'LIGHT', 10, 3000, 2500, '同调怪兽调整＋调整以外的同调怪兽1只以上 这张卡不用同调召唤不能特殊召唤。 ①：1回合1次，把自己墓地1只同调怪兽除外才能发动。这张卡直到回合结束时不受其他卡的效果影响。这个效果在对方回合也能发动。 ②：这张卡被对方破坏的场合，以除外的1只自己的龙族同调怪兽为对象才能发动。那只怪兽特殊召唤。'),
(44508094, 'Stardust Dragon', '星尘龙', 'スターダスト・ドラゴン', 'Synchro Monster', 'Dragon', 'WIND', 8, 2500, 2000, '调整＋调整以外的怪兽1只以上 ①：要让场上的卡破坏的魔法·陷阱·怪兽的效果发动时，把这张卡解放才能发动。那个发动无效并破坏。 ②：这张卡的①的效果适用的回合的结束阶段才能发动。为那个效果发动而解放的这张卡从墓地特殊召唤。'),
(61257789, 'Stardust Dragon/Assault Mode', '星尘龙／爆裂', 'スターダスト・ドラゴン／バスター', 'Effect Monster', 'Dragon', 'WIND', 10, 3000, 2500, '这张卡不能通常召唤，用「爆裂模式」的效果（以及这张卡的②的效果）才能特殊召唤。 ①：魔法·陷阱·怪兽的效果发动时，把这张卡解放才能发动。那个发动无效并破坏。 ②：这张卡的①的效果适用的回合的结束阶段才能发动。为那个效果发动而解放的这张卡从墓地特殊召唤。 ③：场上的这张卡被破坏时，以自己墓地1只「星尘龙」为对象才能发动。那只怪兽特殊召唤。'),
(27196937, 'Stardust Flash', '星尘的残光', '星屑の残光', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地1只「星尘」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(37750912, 'Stardust Illumination', '星尘照耀', 'スターダスト・イルミネイト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从卡组把1只「星尘」怪兽送去墓地。自己场上有着「星尘龙」或者有那个卡名记述的同调怪兽存在的场合，也能不送去墓地特殊召唤。 ②：把墓地的这张卡除外，以自己场上1只「星尘」怪兽为对象才能发动。那只怪兽的等级直到回合结束时上升或下降1星。'),
(13556444, 'Stardust Mirage', '星尘幻象', 'スターダスト・ミラージュ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有8星以上的龙族同调怪兽存在的场合才能发动。这个回合被战斗或者对方的效果破坏送去自己墓地的怪兽尽可能特殊召唤。'),
(80244114, 'Stardust Phantom', '星尘幻影', 'スターダスト・ファントム', 'Effect Monster', 'Spellcaster', 'LIGHT', 1, NULL, NULL, '自己场上存在的这张卡被对方破坏送去墓地时，可以选择自己墓地存在的1只「星尘龙」表侧守备表示特殊召唤。此外，把墓地存在的这张卡从游戏中除外，选择自己场上表侧表示存在的1只龙族的同调怪兽才能发动。选择的怪兽1回合只有1次不会被战斗破坏，这个效果适用的伤害步骤结束时攻击力·守备力下降800。'),
(20590784, 'Stardust Re-Spark', '立于星尘坠地之闪珖', '星墜つる地に立つ閃珖', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '「立于星坠之地的闪珖」在1回合只能发动1张。 ①：特殊召唤的对方怪兽的直接攻击宣言时，那只怪兽的攻击力是自己基本分以上的场合才能发动。那次攻击无效，自己从卡组抽1张。那之后，可以从自己的额外卡组·墓地选1只「星尘」怪兽特殊召唤。'),
(89181369, 'Stardust Shimmer', '星屑的辉煌', '星屑のきらめき', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己墓地存在的1只龙族的同调怪兽发动。直到变成和那只怪兽的等级相同等级为止，把选择的怪兽以外的自己墓地存在的怪兽从游戏中除外，选择的怪兽从墓地特殊召唤。'),
(26268488, 'Stardust Sifr Divine Dragon', '圣珖神龙 星尘零', '聖珖神竜 スターダスト・シフル', 'Synchro Monster', 'Dragon', 'LIGHT', 12, 4000, 4000, '同调怪兽调整＋调整以外的同调怪兽2只以上 这张卡不用同调召唤不能特殊召唤。 ①：自己场上的卡在1回合各有1次不会被战斗·效果破坏。 ②：1回合1次，对方把怪兽的效果发动时才能发动。那个效果无效，场上1张卡破坏。 ③：把墓地的这张卡除外，以自己墓地1只8星以下的「星尘」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(83994433, 'Stardust Spark Dragon', '闪珖龙 星尘', '閃珖竜 スターダスト', 'Synchro Monster', 'Dragon', 'LIGHT', 8, 2500, 2000, '调整＋调整以外的怪兽1只以上 1回合1次，选择自己场上表侧表示存在的1张卡才能发动。选择的卡在这个回合只有1次不会被战斗以及卡的效果破坏。这个效果在对方回合也能发动。'),
(37799519, 'Stardust Synchron', '星尘同步士', 'スターダスト・シンクロン', 'Tuner Monster', 'Machine', 'LIGHT', 4, 1500, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡·墓地存在的场合，把自己场上1只怪兽解放才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。这个效果的发动后，直到回合结束时自己不是同调怪兽不能从额外卡组特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。从卡组把有「星尘龙」的卡名记述的1张魔法·陷阱卡加入手卡。'),
(63184227, 'Stardust Trail', '星尘尾痕', 'スターダスト・トレイル', 'Effect Monster', 'Dragon', 'LIGHT', 4, 500, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡·墓地存在，自己场上的怪兽被解放的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ②：用这张卡为同调素材把「战士」、「同调士」、「星尘」同调怪兽之内任意种同调召唤的场合才能发动。在自己场上把1只「星尘衍生物」（龙族·光·1星·攻/守0）特殊召唤。'),
(74892653, 'Stardust Warrior', '星尘战士', 'スターダスト・ウォリアー', 'Synchro Monster', 'Warrior', 'WIND', 10, 3000, 2500, '同调怪兽调整＋调整以外的同调怪兽1只以上 ①：对方把怪兽特殊召唤之际，把这张卡解放才能发动。那个无效，那些怪兽破坏。 ②：这张卡的①的效果适用的回合的结束阶段才能发动。为那个效果发动而解放的这张卡从墓地特殊召唤。 ③：战斗或者对方的效果让表侧表示的这张卡从场上离开的场合才能发动。从额外卡组把1只8星以下的「战士」同调怪兽当作同调召唤作特殊召唤。'),
(35129241, 'Stardust Wish', '星尘的祈愿', '星屑の願い', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，自己场上的「星尘」同调怪兽为让自身的效果发动而被解放的场合，以那1只怪兽为对象才能发动。那只怪兽特殊召唤。对方不能对应这个效果的发动把魔法·陷阱·怪兽的效果发动。 ②：这张卡的①的效果特殊召唤的怪兽在攻击表示的场合不会被战斗破坏。'),
(91262474, 'Stardust Wurm', '星尘幼龙', 'スターダスト・ヴルム', 'Effect Monster', 'Dragon', 'LIGHT', 1, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡·墓地存在，自己场上有8星以上的龙族同调怪兽存在的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ②：把这张卡解放才能发动。从自己的手卡·墓地选「星尘亚龙」以外的最多2只龙族·光属性·1星怪兽特殊召唤。这个效果特殊召唤的怪兽不能把效果发动。'),
(68543408, 'Stardust Xiaolong', '星尘小龙', 'スターダスト・シャオロン', 'Effect Monster', 'Dragon', 'LIGHT', 1, 100, 100, '自己对「星尘龙」的同调召唤成功时，自己墓地存在的这张卡可以在自己场上表侧攻击表示特殊召唤。这张卡1回合只有1次不会被战斗破坏。'),
(95403418, 'Starduston', '星尘妖', 'スターダストン', 'Effect Monster', 'Fiend', 'DARK', 1, -1, -1, '这张卡不能通常召唤。把自己场上表侧表示存在的名字带有「尘妖」的怪兽任意数量送去墓地的场合才能特殊召唤。这张卡的攻击力·守备力变成送去墓地的那些怪兽数量×1000的数值。只要这张卡在场上表侧表示存在，对方不能把场上盖放的魔法·陷阱卡发动，对方不能把怪兽反转召唤·特殊召唤。自己场上的怪兽数量比对方场上的怪兽数量多的场合，这张卡破坏。'),
(44717069, 'Starfish', '海星', 'スターフィッシュ', 'Effect Monster', 'Aqua', 'WATER', 3, 300, 300, '1回合1次，自己的主要阶段时才能发动。自己场上的全部「海星」的等级上升1星。'),
(94415058, 'Stargazer Magician', '星读的魔术师', '星読みの魔術師', 'Pendulum Effect Monster', 'Spellcaster', 'DARK', 5, 1200, 2400, '①：1回合1次，只让自己场上的灵摆怪兽1只因对方的效果回到自己手卡时才能发动。那1只同名怪兽从手卡特殊召唤。'),
(97729135, 'Staring Contest', '瞪眼对峙', 'にらみ合い', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：自己在额外怪兽区域把怪兽特殊召唤时，以对方的主要怪兽区域1只怪兽为对象才能发动。那只对方怪兽向和那自己的额外怪兽区域的怪兽相同纵列的对方的主要怪兽区域移动。 ②：对方在额外怪兽区域把怪兽特殊召唤时，以自己的主要怪兽区域1只怪兽为对象才能发动。那只自己怪兽向和那对方的额外怪兽区域的怪兽相同纵列的自己的主要怪兽区域移动。'),
(40390147, 'Starliege Lord Galaxion', '辉光皇帝盖勒克希翁', '輝光帝ギャラクシオン', 'XYZ Monster', 'Warrior', 'LIGHT', 4, 2000, 2100, '名字带有「光子」的4星怪兽×2 1回合1次，把这张卡最多2个超量素材取除才能发动。为这个效果发动而取除的超量素材数量的以下效果适用。 ●1个：从手卡把1只「银河眼光子龙」特殊召唤。 ●2个：从卡组把1只「银河眼光子龙」特殊召唤。'),
(61344030, 'Starliege Paladynamo', '辉光公子帕拉迪奥斯', '輝光子パラディオス', 'XYZ Monster', 'Warrior', 'LIGHT', 4, 2000, 1000, '光属性4星怪兽×2 ①：1回合1次，把这张卡2个超量素材取除，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力变成0，那个效果无效。 ②：场上的这张卡被对方破坏送去墓地的场合发动。自己从卡组抽1张。'),
(16643334, 'Starliege Photon Blast Dragon', '辉光龙光子爆龙', '輝光竜フォトン・ブラスト・ドラゴン', 'XYZ Monster', 'Dragon', 'LIGHT', 4, 1800, 2500, '4星怪兽×2 ①：这张卡超量召唤的场合才能发动。从手卡把1只「光子」怪兽特殊召唤。 ②：只要超量召唤的这张卡在怪兽区域存在，自己场上的攻击力2000以上的怪兽不会被对方的效果破坏，对方不能把那些作为效果的对象。 ③：对方回合1次，把这张卡1个超量素材取除，以自己的墓地·除外状态的1只「银河眼光子龙」为对象才能发动。那只怪兽特殊召唤。'),
(15381421, 'Starliege Seyfert', '辉光龙 赛弗特', '輝光竜セイファート', 'Effect Monster', 'Dragon', 'LIGHT', 4, 1800, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从自己的手卡·场上（表侧表示）把龙族怪兽任意数量送去墓地才能发动。把持有和送去墓地的怪兽的原本等级合计相同等级的1只龙族怪兽从卡组加入手卡。 ②：把墓地的这张卡除外，以自己墓地1只光·暗属性的龙族·8星怪兽为对象才能发动。那只怪兽加入手卡。'),
(1003840, 'Starlight Junktion', '星光废品立交桥', 'スターライト・ジャンクション', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '「星光立交桥」的①②的效果1回合各能使用1次。 ①：把自己场上1只调整解放才能把这个效果发动。和解放的怪兽等级不同的1只「同调士」怪兽从卡组特殊召唤。 ②：对方回合自己从额外卡组把同调怪兽特殊召唤的场合，以场上1张卡为对象发动。那张卡回到持有者卡组。'),
(58120309, 'Starlight Road', '星光大道', 'スターライト・ロード', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：要让自己场上的卡2张以上破坏的魔法·陷阱·怪兽的效果发动时才能发动。那个效果无效并破坏。那之后，可以把1只「星尘龙」从额外卡组特殊召唤。'),
(92341815, 'Starlit Papillon', '星空蝶', '星空蝶', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '自己场上的怪兽才能装备。这个卡名的③的效果1回合只能使用1次。 ①：「星空蝶」在自己场上只能有1张表侧表示存在。 ②：对方场上的怪兽的攻击力下降自己场上的有「勇者衍生物」的衍生物名记述的怪兽种类×500。 ③：这张卡被送去墓地的场合，以自己场上1只「勇者衍生物」为对象才能发动。那只自己怪兽把这张卡装备。'),
(5916510, 'Starring Knight', '天翔骑士', '天翔ける騎士', 'XYZ Monster', 'Fairy', 'LIGHT', 4, 1900, 1000, '4星怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡1个超量素材取除才能发动。从手卡把1只光属性怪兽特殊召唤。 ②：这张卡在墓地存在的场合，以自己场上1只天使族·光属性·4星怪兽为对象才能发动。这张卡特殊召唤，把作为对象的怪兽在这张卡下面重叠作为超量素材。这个效果在这张卡送去墓地的回合不能发动。'),
(6278008, 'Starry Dragon''s Cycle', '星霄龙转', '星宵竜転', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以场上1只融合·同调·超量·连接怪兽为对象才能发动。那只表侧表示怪兽回到额外卡组。那之后，可以把回去的怪兽种类（融合·同调·超量·连接）对应的1只以下怪兽从自己·对方的墓地往自己场上特殊召唤。 ●融合：和回去的怪兽相同属性的怪兽 ●同调：比回去的怪兽等级低的怪兽 ●超量：持有和回去的怪兽的阶级相同数值的等级的怪兽 ●连接：和回去的怪兽相同种族的怪兽'),
(21985407, 'Starry Knight Arrival', '圣夜的降临', '聖夜の降臨', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己·对方的主要阶段，可以从以下效果选择1个发动。 ●以自己场上1只龙族·光属性·7星怪兽为对象才能发动。那只怪兽回到持有者手卡。 ●从手卡把1只龙族·光属性·7星怪兽特殊召唤。'),
(59228631, 'Starry Knight Astel', '圣夜骑士团·阿斯特尔', 'ホーリーナイツ・アステル', 'Effect Monster', 'Fairy', 'LIGHT', 4, 500, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只光属性怪兽为对象才能发动。那只怪兽解放，从手卡把1只龙族·光属性·7星怪兽特殊召唤。这个效果在对方回合也能发动。 ②：把墓地的这张卡除外，以自己场上1只龙族·光属性·7星怪兽为对象才能发动。那只怪兽的攻击力直到对方回合结束时上升1000。');